    history_title: "游戏历史图书馆",
    history_intro: "本合集中的每款游戏都有自己的故事——有些已有五千多年历史,有些则问世不到十年。可以按大致的出现顺序在这里阅读,也可以直接跳转到任意一款游戏的完整历史页面。",
    history_dates_note: "这里列出的最古老游戏的年代仅为大致估计——它们的确切起源常常已湮没在历史中,或仍存在学界争议。",
    history_read_more: "查看完整历史 →",
    home_history_title: "好奇这些游戏是从哪里来的吗?",
    home_history_desc: "在这里阅读每款游戏的起源故事,从古埃及到近十年——不是用来挑选游戏,只是纯粹的阅读。",
    home_chess_desc: "经典的棋类游戏。本地双人对战、挑战内置引擎，或通过 Lichess 在线对局。",
    home_go_desc: "古老的围地游戏。本地双人对战或挑战内置引擎，提供三种棋盘尺寸与三个难度等级。",
    home_checkers_desc: "经典的跳吃类棋类游戏。本地双人对战或挑战内置引擎，三个难度等级。",
    home_ur_desc: "一款有 4600 年历史的竞速游戏，重新发掘自古代美索不达米亚。本地双人对战或挑战内置引擎，包含玫瑰花格与踩踏吃子规则。",
    home_morris_desc: "一款历史悠久的策略游戏：摆子与移子，凑成三连。本地双人对战或挑战内置引擎，包含经典的“飞子”残局规则。",
    home_backgammon_desc: "经典的骰子竞速游戏。本地双人对战或挑战内置引擎，包含门柱、收子出局与打吃单子等规则。",
    home_xiangqi_desc: "中国象棋：帅、相、炮等棋子在 9x10 的交叉点棋盘上对弈。本地双人对战或挑战内置引擎，可在传统文字棋子与西式符号棋子之间切换。",
    home_mancala_desc: "世界上历史最悠久的游戏家族之一：在棋盘上播撒棋子，填满自己的粮仓。本地双人对战或挑战内置引擎，包含吃子与额外回合规则。",
    home_reversi_desc: "通过夹住对手的棋子来翻转棋盘的颜色。本地双人对战或挑战内置引擎。",
