    mahjong_new_game: "新局",
    mahjong_shuffle: "重排剩余牌",
    chess_history_intro: "从古印度的一款战争游戏，到如今全世界研究最深入的棋类游戏——国际象棋跨越了大陆与世纪，才演变成今天的样子。",
    go_history_intro: "围棋是至今仍以原始形态被人们对弈的最古老棋类游戏之一——这款关于地盘与棋子的游戏，其根源很可能可以追溯到 2500 多年前的中国。",
    checkers_history_intro: "西洋跳棋（draughts）是一款规则简单、策略深邃的游戏，诞生于一块古老棋盘与一种更新的吃子方式的结合。",
    ur_history_intro: "乌尔皇室游戏距今大约有 4600 年历史，是人类发现的最古老棋类游戏之一——得益于一段跨越两千年的“侦探”工作，它也是极少数至今仍能按照原始规则对弈的古代游戏之一。",
    morris_history_intro: "很少有游戏像九子棋这样，在如此多的时代里被刻在如此多的表面上——从埃及神庙的屋顶，到英国大教堂的回廊。",
    backgammon_history_intro: "西洋双陆棋的家族谱系，几乎贯穿了每一个曾经掷过骰子的文明——从古代美索不达米亚、罗马，一直到现代中东的咖啡馆。",
    xiangqi_history_intro: "象棋与国际象棋有着深厚的共同渊源，却在一千多年的时间里走上了截然不同的道路，最终演变成如今被数以亿计的人们对弈的这款游戏。",
    mancala_history_intro: "曼卡拉不是单独一款游戏，而是一整个游戏家族——地球上最古老的游戏家族之一，都建立在一个简单而普世的动作之上：在坑穴之间移动种子或石子。",
    reversi_history_intro: "一款维多利亚时代的客厅游戏，在相隔一个世纪的时间里被重新发明了两次。",
    fourinarow_history_intro: "一个由重力驱动的简单点子，最终成长为 20 世纪最畅销的游戏之一。",
    gomoku_history_intro: "一款“连成一线”的简单游戏，其规则的极度简洁，反而迫使竞技棋手不得不对它加以修改。",
    tictactoe_history_intro: "这大概是最广为人知的纸笔游戏——它的根源可以追溯到古罗马，在计算机历史上也占有一席之地。",
    senet_history_intro: "这是曾被发现的最古老棋类游戏之一——而它的确切规则，已经失传了数千年。",
    shogi_history_intro: "将棋是日本对国际象棋这一大家族的独特演绎，也是唯一一款被吃掉的棋子不会离开棋局、而是加入吃子一方阵营的主要变体。",
    sudoku_history_intro: "与本合集中的其他游戏不同，数独完全没有古老的传承——它的历史几乎不比个人电脑更悠久。",
    pegsolitaire_history_intro: "这是一款历史悠久到拥有自己宫廷传说的单人解谜游戏，也是趣味数学中一些较为惊人的结论的研究对象。",
    minesweeper_history_intro: "这款游戏有一条标志性规则——第一步绝对安全——而这条规则，只有在电脑（而非印刷页面）能够随需生成全新棋盘之后，才真正得以成为标准。",
    nonogram_history_intro: "一款在地球两端相隔仅几年、被两个人各自独立发明的逻辑谜题——它的名字，正来自其中一位发明者。",
    twenty48_history_intro: "一款几乎完全由其他游戏的创意拼凑而成、只用一个周末就做出来的游戏，被克隆的次数或许超过了此前任何一款网页游戏。",
    mahjong_history_intro: "一款单人配对游戏，它的名字和外观都借自另一款四人游戏，但除此之外二者几乎没有任何共通之处。",
