    impressum_liability_links_body: "本网站包含指向外部第三方网站的链接,特别是 lichess.org 和 paypal.com,我们对其内容没有任何影响力,因此不对这些外部内容承担任何责任。相关链接页面的提供者或运营者始终对其内容负责。这些链接页面在设置链接时已核实是否存在违法内容,当时未发现任何违法内容。但是,在没有具体证据表明存在违法行为的情况下,持续监控链接页面的内容并不合理。如果我们获悉任何违法行为,将立即删除相关链接。",
    impressum_trademarks_heading: "商标",
    impressum_trademarks_body: "历史页面会提到一些商业游戏的名称，以客观说明某种玩法的来源。其中一些名称是其各自所有者的注册商标。PaperGames 与这些所有者没有任何关联，也未获得他们的认可、赞助或审核。这里的所有游戏都是独立实现的，没有使用任何商业版本的素材。",
