    impressum_vat_notice: "根据《德国增值税法》第19条(小型企业条例),本网站不显示增值税。",
    privacy_complaint_body: "您有权就我们对您个人数据的处理向数据保护监管机构投诉。主管机构为:Landesbeauftragte für Datenschutz und Informationsfreiheit Nordrhein-Westfalen (LDI NRW), Kavalleriestraße 2–4, 40213 Düsseldorf, 德国, poststelle@ldi.nrw.de, https://www.ldi.nrw.de。",
    privacy_complaint_heading: "8. 投诉权",
    privacy_controller_body: "根据《通用数据保护条例》(GDPR),负责本网站数据处理的控制者为:",
    privacy_controller_heading: "1. 控制者",
    privacy_hosting_body: "本网站通过 GitHub Pages 托管,该服务由 GitHub, Inc.(88 Colin P. Kelly Jr. Street, San Francisco, CA 94107, USA,Microsoft Corporation 的子公司)提供。当您访问本网站时,GitHub 会自动收集您的浏览器传输的所谓服务器日志文件。这些通常包括:IP地址、请求的日期和时间、请求的文件、传输的数据量、请求状态、浏览器类型和版本、操作系统以及来源页面(引荐来源网址)。这些数据由 GitHub 处理,不会以可识别个人身份的形式提供给我们。法律依据为《通用数据保护条例》第6条第1款(f)项(为本网站提供技术上无误且安全的服务的合法利益)。有关 GitHub 处理数据的更多信息,请参阅 GitHub 隐私声明: https://docs.github.com/site-policy/privacy-policies/github-general-privacy-statement。",
    privacy_hosting_heading: "2. 托管",
    privacy_lichess_body: "在线国际象棋功能是可选的,仅在您明确选择通过\"使用 Lichess 登录\"登录时才会启用。这样做会从您的浏览器打开一个到 lichess.org 的 OAuth2 连接;您直接通过 Lichess 登录,PaperGames 绝不会接收或存储您的密码。Lichess 颁发的访问令牌仅存储在您浏览器的本地存储(localStorage)中,仅用于代表您与 Lichess 服务器交换着法和对局。Lichess 对您数据的处理完全受其自身隐私政策约束: https://lichess.org/privacy。PaperGames 是一个独立项目,与 Lichess 没有任何关联,也未获得其认可或授权。",
    privacy_lichess_heading: "4. Lichess(可选)",
    privacy_no_tracking_body: "本网站不使用任何分析或跟踪工具、广告网络,也不使用网络字体或其他可能触发向第三方传输数据的第三方嵌入内容——上述技术上必需的 GitHub Pages 托管以及您自己明确触发的与 Lichess 或 PayPal 的连接除外。您的数据不会出于广告或分析目的与第三方共享。",
    privacy_no_tracking_heading: "6. 无分析、无广告、无数据共享",
    privacy_paypal_body: "\"关于\"页面提供了一个可选的 PayPal 捐赠链接。仅访问该页面不会向 PayPal 传输任何数据。只有当您主动点击链接或二维码并打开 paypal.com 时,PayPal(PayPal (Europe) S.à r.l. et Cie, S.C.A., 22-24 Boulevard Royal, L-2449 卢森堡)才会根据其自身责任并按照 PayPal 的隐私政策处理您的数据: https://www.paypal.com/webapps/mpp/ua/privacy-full。二维码本身由本网站在本地生成,不会从第三方服务器加载任何内容。",
    privacy_paypal_heading: "5. PayPal 捐赠链接",
    privacy_rights_body: "在处理个人数据的范围内,您根据适用法律享有以下权利:访问权(GDPR第15条)、更正权(第16条)、删除权(第17条)、限制处理权(第18条)、数据可携权(第20条)以及反对处理权(第21条)。如需行使这些权利,请通过上述电子邮件地址与我们联系。",
    privacy_rights_heading: "7. 您的权利",
    privacy_storage_body: "PaperGames 不使用 Cookie。为实现其功能,本网站仅依赖浏览器内置的 localStorage 和 sessionStorage。它们用于在您的设备本地存储:进行中的游戏、个人设置(如语言、棋盘样式)、您的最佳成绩,以及——如果您登录在线国际象棋功能——您的 Lichess 访问令牌。这些数据永远不会离开您的设备,也不会传输给我们或任何第三方;它们的存在仅仅是为了提供您明确请求的功能(继续游戏、保留设置、保持登录状态)。因此,根据《德国电信数字服务数据保护法》(TDDDG)第25条第2款第2项,此存储是提供您明确请求的电信媒体服务所严格必需的。因此不需要征得同意,这也是本网站不显示 Cookie 同意横幅的原因。您可以随时通过浏览器设置删除这些数据。",
    privacy_storage_heading: "3. 本地存储(无 Cookie)",
