    release_v223: "离线保存更加可靠，游戏按系列分组，多米诺骨牌新增“三角形”变体，“谁拿走了蛋糕？”新增“猫和鱼”主题并提供更多提示。",
    release_v224: "卡牌对决：四套实力相当的牌组，可与电脑对战，也可两人在同一设备上对战。",
    release_v225: "童话反派：六个格林童话反派，各有目标，适合 2 至 4 人。",
    release_v226: "森林村庄：森林动物们历经四季建设村庄，适合 1 至 4 人。",
    release_v227: "冒险之书：单人角色扮演游戏——创建英雄，探索洞穴、高塔或森林。",
    release_v228: "首页底部的小链接通往 Quillwild，一个正在制作的新项目。",
    release_v229: "首页现在更短了，各类别有了自己的页面。",
    release_v230: "卡牌对决：现在每张卡牌都有图画了。",
    release_v234: "七巧板新增难度“只有轮廓”，含29个新图形。",
    release_v235: "“找东西”新增九个房间和40多幅新图画；“谁拿走了蛋糕？”新增一家人主题以及孩子和宝藏主题。",
    release_v236: "“找东西”新增浴室、地下室和卧室；“谁拿走了蛋糕？”新增五个房间和七件家具。",
    release_v237: "“新游戏”现在显示最新的10款游戏。",
    release_v241: "Waldsiedlung更新了规则和说明并更改了名称；旧游戏存档将被删除。",
    release_v242: "游戏更换了名称和地址，旧地址会自动跳转。",
    release_v243: "离线存储减少了重新加载；修正了阿拉伯语间距，选中按钮改为黑色，“洗牌”会先询问，规则页面顶部也增加了返回链接。",
    release_v244: "游戏打开即可开始；结果窗口新增“再玩一次”；“新游戏”保留在棋盘旁；国际象棋有了单独的双人按钮。",
    release_v245: "游戏页面的页眉只占一行，不再显示网站导航；设置移入菜单；开始后控制面板会收起，更多棋盘能完整显示在屏幕上。",
    release_v246: "所有分类页面的游戏卡片都成为大面积点击区；儿童页面在一页内以大图标显示全部儿童游戏；“大棋盘”让小棋盘更易点按；Cake 不再列入儿童游戏。",
    release_v249: "页面所需数据更少，加载更快。新增游戏：Kleeberg 和牧场伙伴。",
    release_v250: "Steckwürfeln 现在可以点按孔洞，Klappenkasten 会显示电脑合上了哪些，宾果最多可选四个电脑对手。Durak 和 Skat 的按钮恢复正常。",
    release_v248: "新增7款游戏（宾果、三款骰子游戏和三款儿童益智游戏），箭头游戏新增最高难度，猫咪游戏新增提示按钮，搜索更好用，并新增纸牌游戏页面。",
    release_v247: "所有游戏统一了名称和状态文字（“对战电脑”“两人共用一台设备”“新游戏”“轮到你了”）；每个游戏页面都有“主页”按钮；32 个游戏中的“撤销”会同时撤回你的一步和电脑的应对。",
    release_v240: "游戏名称已在全部12种语言中更改。",
    release_v239: "规则和历史页面描述中已移除受保护的游戏名称。",
    release_v238: "简要规则现在会匹配所选的蛋糕主题和图片搜索模式。",
    release_v233: "箭头“困难”：会滑动的箭头、11×11格，以及带三颗心的新难度“大师”。",
    release_v232: "走法提示可以在设置中关闭，“谁拿走了蛋糕？”新增了三个主题。",
    release_v231: "找不同新增了一种玩法：找东西。",
