    home_coming_soon_title: "即将推出",
    home_coming_soon_intro: "以下游戏正在考虑加入未来的更新：",
    home_coming_soon_multiplayer_title: "双人策略游戏",
    home_coming_soon_solo_title: "单人解谜游戏",
    game_four_in_a_row: "四子连线",
    home_four_in_a_row_desc: "在对手之前把四枚棋子连成一线。本地双人对战或挑战内置引擎。",
    game_gomoku: "五子棋",
    home_gomoku_desc: "在与围棋相同大小的棋盘上，率先连成五子。本地双人对战或挑战内置引擎。",
    game_tictactoe: "井字棋",
    home_tictactoe_desc: "在 3x3 的格子里连成三子——纸笔游戏的经典。可本地双人对战，也可对战内置引擎，它在“困难”难度下从不输棋。",
    tictactoe_board_label: "井字棋棋盘",
    game_alquerque: "阿尔盖克(Alquerque)",
    home_alquerque_desc: "西洋跳棋的中世纪祖先：双方各 12 枚棋子，在 5x5 的线格棋盘上跳吃，且吃子是强制性的。可本地双人对战，也可对战内置引擎。",
    alquerque_board_label: "阿尔盖克棋盘",
    msg_keep_jumping: "继续用这枚棋子跳吃。",
    alquerque_history_intro: "一种在线格棋盘上进行的小型跳吃游戏，在 13 世纪的西班牙被记录下来——也是西洋跳棋的祖先。",
    game_pairs: "配对",
    home_pairs_desc: "翻开两张牌，找出成对的牌：经典的翻牌配对游戏，采用简单的黑白图形、动物、水果和蔬菜或交通工具。可单人挑战步数，可两人在同一设备上对战，也可对战内置引擎。",
    game_futoshiki: "不等式数独",
    home_futoshiki_desc: "填满方格，使每行每列都恰好包含每个数字一次，并且两格之间的每个符号都指向较小的数字。尺寸从4x4到6x6，每次新生成，只有唯一解。",
    futoshiki_board_label: "不等式数独棋盘",
    futoshiki_size_label: "方格大小",
    futoshiki_history_intro: "一种日本数字谜题，名字的意思就是“不等式”：在拉丁方阵的格子之间加上小小的符号。",
    game_foxandgeese: "狐狸与鹅",
    home_foxandgeese_desc: "在33个点的十字棋盘上进行的中世纪狩猎游戏：一只狐狸对13只鹅。可以选择任意一方，本地双人对战或对战内置引擎。",
    foxandgeese_board_label: "狐狸与鹅棋盘",
    foxandgeese_history_intro: "来自中世纪欧洲的狩猎游戏：一只狐狸、一群鹅和一块十字形的棋盘。",
    game_seega: "塞加棋",
    home_seega_desc: "在5x5棋盘上进行的埃及布子与夹吃游戏：双方先各放12枚棋子，然后通过夹住对方来吃子。本地双人对战或对战内置引擎。",
    seega_board_label: "塞加棋棋盘",
    seega_history_intro: "一种来自埃及、1836年有记载的游戏：每次放两枚棋子，然后用自己的两枚棋子把对方夹住。",
    game_romme: "拉米牌（Rommé）",
    home_romme_desc: "用两副牌和六张王牌玩的德式拉米：打出同点组和顺子，可以往桌上任何牌组里加牌，最先出完手牌者胜。2至4人，可对战电脑或在同一台设备上玩。",
    romme_history_intro: "德国用两副牌加王牌玩的拉米牌，是众多收集同点组和顺子的游戏之一。",
