    game_senet: "塞尼特棋",
    home_senet_desc: "已知最古老的棋类游戏之一，来自古埃及。本地双人对战或挑战内置引擎。",
    game_shogi: "将棋",
    home_shogi_desc: "日本象棋：被吃掉的棋子会转投对方阵营，重新加入战斗。本地双人对战或挑战内置引擎。",
    game_card_tactics: "卡牌战术",
    home_card_tactics_desc: "一场由五张不断轮换的移动卡牌所决定的、节奏明快而优雅的对决。本地双人对战或挑战内置引擎。",
    cardtactics_neutral_card: "下一张卡牌：",
    cardtactics_history_intro: "抽象策略游戏家族中一个较为现代的新成员，围绕一个建立在类国际象棋走法之上的小巧构思：并非每枚棋子都拥有固定的走法，而是由一副共享的卡牌，决定每一回合可能出现的走法。",
    game_hnefatafl: "赫纳弗塔福（维京棋）",
    home_hnefatafl_desc: "一款不对称的北欧游戏：国王必须逃脱，攻方必须将他围困。本地双人对战或挑战内置引擎。",
    hnefatafl_history_intro: "北欧历史最悠久的棋类游戏家族之一，在国际象棋传入之前的数个世纪里，一直在整个维京世界流传。",

    game_tablut: "塔布鲁棋",
    home_tablut_desc: "塔夫尔家族中体量最大、文献记录最完整的一款：9x9 棋盘上，国王要设法抵达角格，攻方则要抢先将他围死。",
    tablut_history_intro: "多亏一位十八世纪博物学家的笔记本,它成了整个塔夫尔家族中文献记录最完整的一员。",

    game_wall_maze: "墙壁迷宫",
    home_wall_maze_desc: "在建造木墙阻挡对手的同时，率先冲向棋盘的另一端。本地双人对战或挑战内置引擎。",
    wallmaze_history_intro: "墙壁迷宫是一款现代抽象策略游戏，只需加上几道墙，就把一场简单的网格赛跑变成了真正的战术对决。",
    wallmaze_wall_mode_start: "放置木墙",
    wallmaze_wall_mode_cancel: "✕ 取消",
    wallmaze_wall_orientation_h: "横向",
    wallmaze_wall_orientation_v: "纵向",
    wallmaze_wall_confirm: "✓ 放置",
    game_hex: "六贯棋",
    home_hex_desc: "在对手连通之前，率先连通六边形棋盘上属于你的两条边。本地双人对战或挑战内置引擎。",
    hex_legend_r: "红方：上 下",
    hex_legend_b: "蓝方：左 右",
    hex_history_intro: "一个罕见的案例：同一款简洁优雅的游戏被两个人各自独立发明了两次，而这两人后来都因完全不同的成就而闻名于世。",
    game_halma: "哈尔玛跳棋",
    home_halma_desc: "把你所有的棋子送过棋盘，进驻对手的起始营地。本地双人对战或挑战内置引擎。",
    halma_history_intro: "这是一款美国人对一款更古老的德国游戏的改造，作为一种易学却依然考验周密布局的简单竞速游戏，流行了一个多世纪。",
    game_sternhalma: "跳棋",
    home_sternhalma_desc: "带领你全部十枚珠子穿过星形棋盘，进驻对面的角。本地双人对战或挑战内置引擎。",
    sternhalma_history_intro: "源自更早的哈尔玛跳棋、棋盘改为六角星形的后继者，曾以一个与其真实起源毫无关系的异域名字来营销。",

    game_dotsandboxes: "点格棋",
    home_dotsandboxes_desc: "在点与点之间连线以完成方格并将其收入囊中——谁完成一个方格，谁就再走一步。可选 4 × 4、5 × 5、6 × 6 或 8 × 8 方格，可本地双人对战，也可对战内置引擎。",
    dotsandboxes_new_game: "新游戏",
    dotsandboxes_board_size_label: "棋盘大小",
    dotsandboxes_board_size_4: "4 × 4 方格（短局）",
    dotsandboxes_board_size_5: "5 × 5 方格",
