    dotsandboxes_history_intro: "一款有一百多年历史的纸笔游戏，也是严肃数学研究的真正对象。",
    game_fanorona: "法诺罗纳棋",
    home_fanorona_desc: "马达加斯加的国家棋类游戏:在5x9的网格线上滑动棋子,通过接近或后退吃子。可本地双人对战,也可对战内置引擎。",
    game_konane: "科纳内棋",
    home_konane_desc: "夏威夷跳棋:整个棋盘上摆满交替排列的棋子,以直线(非对角线)的连续跳吃移动,并以独特的双子移除仪式开局。可本地双人对战,也可对战内置引擎。",

    fanorona_history_intro: "马达加斯加的国家棋类游戏,承载着真正的文化自豪感,也伴随着一些传说。",

    fanorona_choose_capture_type: "接近吃与后退吃两种走法都可行——请选择其中一种:",
    fanorona_capture_approach_btn: "接近吃",
    fanorona_capture_withdrawal_btn: "后退吃",
    fanorona_continue_capturing: "你可以用这枚棋子继续吃子,也可以就此停止。",
    fanorona_done_capturing_btn: "结束吃子",
    game_ludo: "飞行棋 (Ludo)",
    home_ludo_desc: "经典的十字形竞速游戏,源自古印度的帕奇西棋。你自己操控一种颜色,对抗最多三名电脑对手(共2-4名玩家),也可以在本地轮流传递设备进行对战。",
    ludo_mode_hotseat: "两人共用一台设备",
    ludo_num_players: "玩家人数:",
    ludo_roll_die: "掷骰子",
    ludo_history_intro: "这是印度最古老的棋类游戏之一,经现代化、批量生产后流传至今的后裔。",

    konane_history_intro: "一款由石子与策略构成的夏威夷原住民传统游戏,其棋盘直接雕刻在曾经用来对弈的土地之上。",
    konane_continue_jumping: "你可以继续用这枚棋子跳吃,也可以就此停止。",
    konane_done_jumping_btn: "结束跳吃",
    game_surakarta: "苏拉卡尔塔棋",
    home_surakarta_desc: "印度尼西亚的环形轨道吃子游戏:普通的单步移动永远不会吃子,只有沿棋盘四角环形轨道滑动的走法才能吃子。可本地双人对战,也可对战内置引擎。",
    surakarta_history_intro: "一款传统的印度尼西亚棋类游戏,得名于人们相信它起源于其上的爪哇岛城市。",

    game_marblepush: "推珠棋",
    home_marblepush_desc: "把对手的6颗弹珠推出六边形棋盘即可获胜。支持本地双人对战，或挑战内置电脑，完整支持推挤与整排横移的规则。",
    marblepush_history_intro: "一种在六边形棋盘上进行的双人推挤游戏，唯一的吃子方法就是把对方的弹珠推出棋盘边缘。",
    marblepush_selection_hint: "点击高亮的格子即可移动当前选中的弹珠，也可以点击下方按钮清除选择。",
    marblepush_clear_selection_btn: "清除选择",

    game_baghchal: "虎棋(Bagh-Chal)",
    home_baghchal_desc: "尼泊尔传统狩猎游戏:4只老虎对战20只山羊,棋盘为方形5x5的阿尔克格式(alquerque)线格。可本地双人对战,也可对战内置引擎,任选一方。",

    baghchal_history_intro: "尼泊尔最具代表性的传统棋类游戏:老虎在纵横交错的线格上猎捕山羊,其渊源远比任何有文字记载的规则都要古老。",


    game_amazons: "亚马逊棋",
    home_amazons_desc: "移动一枚像皇后一样行走的亚马逊棋子，然后从它的新位置射出一支永久性的箭，逐步封锁棋盘。可本地双人对战，也可对战内置引擎。",
    amazons_history_intro: "亚马逊棋是一款现代抽象策略游戏，玩法核心是通过逐格、永久地封锁棋盘来争夺地盘。",

    game_sudoku: "数独",
    home_sudoku_desc: "在 9x9 网格中填入数字，使每一行、每一列和每一个 3x3 小九宫格都恰好包含 1 到 9。每一局都是全新生成、拥有唯一解，共三个难度等级。",
    game_peg_solitaire: "孔明棋",
    home_peg_solitaire_desc: "让棋子互相跳过，直到只剩一枚——可以用英式十字棋盘，也可以选其他几种棋盘，从 6×6 正方形到维格勒布的 45 孔十字。",
    game_minesweeper: "扫雷",
    home_minesweeper_desc: "借助数字提示找出所有安全的格子，同时避免触发隐藏的地雷。",
    game_nonograms: "数织",
    home_nonograms_desc: "根据行列上的数字线索，一格一格地揭示出隐藏的图案。每一局都是全新生成、拥有唯一解，共三种尺寸。",
    game_2048: "2048",
    home_2048_desc: "滑动并合并互不相邻，在棋盘填满之前凑出 2048。达成之后仍可继续游戏，把最高分数再往上推。",
    game_mahjong_solitaire: "麻将接龙",
    home_mahjong_solitaire_desc: "通过配对相同的图案，清空层层叠叠的牌型。每一局都保证有解。",
    game_freecell: "空当接龙",
    home_freecell_desc: "经典的纸牌接龙游戏，只要走法得当，几乎每一局都能获胜。支持完整的连续移牌，以及一键收牌到基础堆。",
    freecell_new_game: "新局",
    freecell_collect: "收牌到基础堆",
    freecell_history_intro: "一个有着上百年历史的纸牌游戏家族，其中最著名的变体，却颇为特别地，主要是因为一款十分具体的 1990 年代软件而出名。",
    game_lightswitch: "电灯开关",
    home_lightswitch_desc: "点击一个格子，可以切换它和相邻格子的开关状态。关掉所有灯即可获胜——每个谜题的生成方式都保证一定有解。",
    lightswitch_new_game: "新游戏",
    lightswitch_level_easy: "简单(5步可解)",
    lightswitch_level_medium: "中等(10步可解)",
    lightswitch_level_hard: "困难(20步可解)",
    lightswitch_history_intro: "这是一款诞生于20世纪90年代的手持电子益智玩具，其简单的按键网格背后，竟隐藏着一段真正精妙的数学。",
    nav_impressum: "法律声明",
    nav_privacy: "隐私政策",
    about_lichess_disclaimer: "PaperGames的在线国际象棋功能通过lichess.org的公开API运行。PaperGames是一个独立项目,与Lichess没有关联,也未获得Lichess的认可或审查。",
    about_trademarks: "历史页面会提到一些商业游戏的名称，以客观说明某种玩法的来源。其中一些名称是其各自所有者的注册商标。PaperGames 与这些所有者没有任何关联，也未获得他们的认可、赞助或审核。这里的所有游戏都是独立实现的，没有使用任何商业版本的素材。",
    nikoli_trademark_heading: "关于名称的说明",
    nikoli_trademark_notice: "数独（Sudoku）、カックロ（Kakuro）和スリザーリンク（Slitherlink）这些名称是出版社 Nikoli 在日本的注册商标，橋をかけろ（Hashiwokakero）则是 Nikoli 发表该谜题时使用的名称。PaperGames 与 Nikoli 没有任何关联，也未获得 Nikoli 的支持或审核，因此在日文版中使用其他名称。这些谜题类型本身是自由的；这里的每个谜题都在设备上重新生成。",

