    game_schafkopf: "Schafkopf",
    home_schafkopf_desc: "用德式纸牌的巴伐利亚四人纸牌游戏：你对三台电脑，玩叫A局、温茨局和单打局，有施耐德、全墩、连续王牌和计分表。只计分数。",
    sf_history_intro: "羊头牌（Schafkopf）最早于1782年在萨克森被提及；第一次明确属于巴伐利亚的牌局记录于1849年。",
    quickrules_schafkopf_1: "不叫或宣布一种玩法：叫A局（你叫一张A，持有它的人是你的搭档）、温茨局或单打局。",
    quickrules_schafkopf_2: "奥伯和温特是大将牌（温茨局中只有温特）；要跟花色。被叫的A在其花色被出时必须打出。",
    quickrules_schafkopf_3: "庄家一方需要120分中的61分。施耐德、全墩和连续王牌会提高得分。",
