    game_canasta: "Canasta",
    home_canasta_desc: "经典的双人拉米类游戏，用108张牌：同点数的组合、七张牌的卡纳斯塔、王牌和2是百搭、红3和黑3。你对电脑，打到5000分，或短局打到2000分。",
    cn_history_intro: "卡纳斯塔于1939年在乌拉圭蒙得维的亚发明，1949年传到纽约。",
    quickrules_canasta_1: "从牌堆摸两张牌，或拿走整个弃牌堆——最上面那张牌必须立刻放进组合。",
