    game_bridge: "Bridge",
    home_bridge_desc: "四人定约桥牌：你和电脑搭档对两台电脑。用按钮引导叫牌，明手摊在桌上，计分方式为芝加哥（四副牌）或盘式。",
    br_history_intro: "桥牌源于惠斯特；已知最早的规则（“Biritch, or Russian Whist”）写于1886年，定约桥牌始于1925年。",
    quickrules_bridge_1: "叫出你方能赢得超过六墩的墩数，并指定将牌花色或无将；最高的叫品成为定约。",
    quickrules_bridge_2: "庄家打两手牌：明手（庄家的搭档）摊开。要跟出同花色；最大的将牌获胜。",
