    game_tenpairs: "凑十对",
    home_tenpairs_desc: "纸笔划数字谜题：划掉相同或相加等于10、并且能互相看到的两个数字。没有可划的就把剩下的数字补写到后面。经典开局或随机开局，三个难度。",
    tp_history_intro: "来自学生作业本的纸笔谜题；它的起源没有记载。",
    quickrules_tenpairs_1: "点两个相同（3和3）或相加等于10（3和7）的数字把它们划掉。",
    quickrules_tenpairs_2: "它们必须互相看得到：横、竖或斜着相邻，或者中间只有已划掉的格子；横向也可以跨过行尾。",
    quickrules_tenpairs_3: "卡住了？点“补写”：剩下的数字会在最后再写一遍（最多5次）。划掉所有数字就赢了。",
