    game_mathcross: "计算网格",
    home_mathcross_desc: "把1到9各填一次，让每一行和每一列的算式都成立——从左往右计算。三个难度，总是只有一个解，不用猜。",
    mc_history_intro: "由行和列中的算式组成的数字谜题，与古老的1到9幻方是亲戚。",
    quickrules_mathcross_1: "把1到9填进方格，每个数正好用一次。",
    quickrules_mathcross_2: "每一行和每一列都要得出它的结果。从左往右（从上往下）依次计算，不先算乘法：3 + 4 × 2 = 14。",
    quickrules_mathcross_3: "先点一个方格，再点一个数。填满的行或列会显示✓或✗，表示是否成立。",
    game_cardduel: "卡牌对决",
