    home_villains_desc: "每位玩家扮演格林童话里的一个反派，各有目标——女巫、大灰狼、侏儒怪等——其他人则派英雄来阻挠。2 至 4 人，可与电脑对战或在同一设备上游戏。",
    quickrules_villains_1: "率先完成你的反派的目标——目标卡上会显示还差什么。",
