    quickrules_forestvillage_2: "每回合派出一名工人、建造一张卡，或在工人全部派出后切换季节。每派出两名工人，生产卡再次产出资源。",
    quickrules_forestvillage_3: "向阳洼地有六张明牌。配对动物可使费用减少一根羽毛。每个村庄最多12张牌。",
