    ab_room_cave_5: "洞穴通向一座高高的大厅，你的脚步声在回响。",
    ab_room_cave_6: "闪闪发光的沙子铺满地面，在靴子下沙沙作响。",
    ab_room_cave_7: "冷风从岩缝里吹出来。",
    ab_room_cave_8: "这里长着椅子那么大的蘑菇，散发着泥土的气味。",
    ab_room_cave_9: "一条地下溪流在石槽里哗哗流过。",
    ab_room_cave_10: "一面墙上画满了奇怪的星星。",
    ab_room_cave_11: "钟乳石像石头冰柱一样从洞顶垂下。",
    ab_room_cave_12: "一个小侧洞，有人在这里留下了一条旧毯子。",
    ab_room_cave_13: "小路爬上光滑的岩石，青苔让它们很滑。",
    ab_room_cave_14: "几只蝙蝠在黑暗的角落里睡觉，你踮着脚走过。",
    ab_room_cave_15: "一间圆形石室，地面光滑得像被打磨过。",
    ab_room_cave_16: "绿色的苔藓给岩壁镀上一层淡淡的光。",
    ab_room_cave_17: "这里曾经有一座索桥，如今只剩下桩子。",
    ab_room_cave_18: "这里的空气很暖和，深处某个地方传来隆隆声。",
    ab_room_cave_19: "到处是水晶碎片，好像一块大石头炸开了。",
    ab_room_cave_20: "一个安静的角落，你的灯投下长长的影子。",
    ab_room_tower_1: "摆满落灰书籍的书架一直顶到天花板。",
    ab_room_tower_2: "一道螺旋楼梯盘旋而上，台阶吱吱作响。",
    ab_room_tower_3: "几只渡鸦站在房梁上，用亮晶晶的眼睛盯着你。",
    ab_room_tower_4: "一间旧厨房，冰冷的灶台上挂着一口锅。",
    ab_room_tower_5: "透过一扇圆窗，你看见远远的下方是森林。",
    ab_room_tower_6: "一间书房，里面有张巨大的书桌，墨水瓶里的墨水早已干了。",
    ab_room_tower_7: "玻璃墙后面，齿轮慢慢转动。嘀嗒，嘀嗒。",
    ab_room_tower_8: "一条挂满肖像的长廊，画中人的眼睛好像在跟着你转。",
    ab_room_tower_9: "一个满是地图的房间，其中一张画着一座和这里一样的塔。",
    ab_room_tower_10: "桌上点着蜡烛，可这里好像一个人也没有。",
    ab_room_tower_11: "一间储藏室，摆满装着干草药和彩色粉末的罐子。",
    ab_room_tower_12: "风从一扇破百叶窗里呼啸而入。",
    ab_room_tower_13: "一间音乐室，一架竖琴自己弹出了一个音。",
    ab_room_tower_14: "一座窄窄的木板桥从一面墙通到另一面墙。",
    ab_room_tower_15: "一间卧室，有张带帐幔的床，帐子上满是破洞。",
    ab_room_tower_16: "一间工坊，里面有架望远镜指向天空。",
    ab_room_tower_17: "地上到处是黑色的羽毛。",
    ab_room_tower_18: "墙上挂着一面镜子，可镜中映出的是另一个房间。",
    ab_room_tower_19: "一个小阳台，高处的风带着雨的气味。",
    ab_room_tower_20: "一座凉爽的大厅，地面铺着黑白相间的地砖。",
    ab_room_forest_1: "雾气悬在林间，你几乎看不见自己的手。",
    ab_room_forest_2: "一片开满鲜花的空地，蜜蜂在阳光下嗡嗡飞舞。",
    ab_room_forest_3: "一条长满蕨类的老路。",
    ab_room_forest_4: "一棵空心树，大得能让人站在里面。",
    ab_room_forest_5: "一个小池塘，你一走近，青蛙就跳进水里。",
    ab_room_forest_6: "手臂那么粗的树根横在路上。",
    ab_room_forest_7: "鸟儿在高高的树冠上歌唱。",
    ab_room_forest_8: "草地上有一圈白色的石头。",
    ab_room_forest_9: "黑莓丛沿着一道石墙生长。",
    ab_room_forest_10: "地面长满苔藓，又软又绿，四周十分安静。",
    ab_room_forest_11: "一根倒下的树干横在沟上，像一座桥。",
    ab_room_forest_12: "一座废弃的小屋，门半开着。",
    ab_room_forest_13: "高高的松树在风中吱嘎作响。",
    ab_room_forest_14: "沼泽上方，小小的光点在跳舞。",
    ab_room_forest_15: "一棵巨大的橡树，树皮上刻着一张脸。",
    ab_room_forest_16: "蘑菇长成了一个完美的圆圈。",
    ab_room_forest_17: "一条小溪潺潺流过光滑的卵石。",
    ab_room_forest_18: "一片阴暗的灌木丛，树枝刮着你的袖子。",
    ab_room_forest_19: "一座阳光明媚的小山，从这里看，下面的雾气像一片海。",
    ab_room_forest_20: "古老的石阶从两棵白桦树之间穿过。",
    home_adventurebook_desc: "一款单人角色扮演游戏：创建英雄，一间一间地探索洞穴、高塔或森林，在检定和战斗中掷骰子，把遗失的宝物带回来。简单、中等或困难。",
    quickrules_adventurebook_1: "创建英雄，然后找到这个地方的宝物并带回入口。",
    quickrules_adventurebook_2: "检定：两颗骰子加上属性值需达到所示数字，结果会连同算式一起显示。",
    quickrules_adventurebook_3: "战斗按回合进行：攻击、防御、使用物品、职业技能或逃跑。每走一步游戏都会存档。",
