    game_pentomino: "五连块拼图",
    home_pentomino_desc: "把十二块由五个正方形组成的拼块放进长方形——点一下就能旋转和翻转，不用拖动。可以在四种尺寸里自由摆放，也可以玩给出起始拼块、只有一个解的题目。",
    pt_history_intro: "十二块各由五个正方形组成的拼块：亨利·杜德尼在1907年发表了这个谜题，所罗门·哥隆在1953年把它们命名为“五连块”（pentomino）。",
    quickrules_pentomino_1: "用拼块填满长方形；每个格子正好被覆盖一次。",
    quickrules_pentomino_2: "在格子下方选一块，旋转或翻转后，点它的圆点要放的格子。点已放的拼块可以重新拿起。",
    quickrules_pentomino_3: "选择“给出起始拼块”时，有些拼块固定不动，其余拼块只有一种放法。",
    pt_mode_label: "玩法：",
    pt_mode_free: "自由摆放",
