    msg_pt_place: "需要时旋转或翻转，然后点它的圆点要放的位置。",
    msg_pt_nofit: "这块放不进那里。",
    msg_pt_fixed: "这块是固定的。",
    msg_t_pt_picked: "已拿起拼块{s}。",
    msg_pt_won: "长方形填满了——解开了！",
