    msg_t_pt_info: "已放：{n} / {m} 块",
    game_arrows: "箭头",
    home_arrows_desc: "点一下箭头，只要没有别的箭头挡路，它就会滑出格子。把整个格子清空；每道题都有解，可以撤销、看提示，没有时间限制。在“困难”和“大师”中，被挡住的箭头会向前滑，可能会卡住。",
    aw_history_intro: "只能朝一个方向滑动的拼块，是1880年风靡一时的滑块谜题的亲戚；用箭头的这种玩法是新近出现的谜题。",
    quickrules_arrows_1: "点一下箭头：如果到边缘的路是空的，它就朝自己的方向离开格子。",
    quickrules_arrows_2: "如果有别的箭头挡路，什么也不会发生——先把那一个移出去。在“困难”和“大师”中，它会滑到那支箭头前。",
    quickrules_arrows_3: "把整个格子清空。每道题都有解；“提示”会标出一个可以出去的箭头。",
    aw_win_title: "格子清空了！",
    aw_aria_cell: "第{R}行，第{C}列",
