    aw_dir_1: "右",
    aw_dir_2: "下",
    aw_dir_3: "左",
    msg_aw_start: "点一下箭头，把它送出格子。",
    tg_level_outline: "只有轮廓",
    game_loosen: "解开圆环",
    home_loosen_desc: "互相扣住的圆环，每个都有一个缺口：转动它们——扣住的圆环会反向跟着转——直到它们一个接一个脱开。三个难度，显示最少步数，可撤销和提示。",
    lr_history_intro: "圆环谜题由来已久——九连环大约在1500年就已有记载；这种带缺口的平面玩法是新的。",
    quickrules_loosen_1: "点一个圆环：它顺时针转四分之一圈，和它扣住的圆环反向转动。",
    quickrules_loosen_2: "当圆环的缺口正好在扣住的那个圆环压在上面的交点处时，它就自由了——点它就能取出。",
    quickrules_loosen_3: "取出所有圆环；先取两端的。“提示”会显示一步。",
