    game_weidefreunde: "牧场伙伴",
    home_weidefreunde_desc: "适合儿童的卡牌骰子游戏：掷动物骰子，把牛、羊、猪、鸡和马这五种农场动物收集到自己的牧场上。只有图画，不用识字，没有时间限制。可与电脑对战，或最多四人共用一台设备。",
    weidefreunde_history_intro: "用图画代替数字、并且可以收集卡牌的游戏，是小朋友最早玩的游戏之一，这款游戏把两者结合在一起。",
    quickrules_weidefreunde_1: "掷骰子。骰子上是一种动物或农夫。",
    quickrules_weidefreunde_2: "如果院子里有这种动物的卡牌，而你的牧场上还没有，卡牌就归你。掷到农夫时，可以拿走任意一张你还缺的卡牌。否则，把院子里的一张卡牌送回去。",
    quickrules_weidefreunde_3: "最先让牧场上集齐五种动物的人获胜。",
