    wf_howto_title: "玩法说明",
    wf_howto_1: "掷骰子，上面是一种动物或农夫。",
    wf_howto_2: "如果你还没有这种动物，院子里这种动物的卡就移到你的牧场上。",
    wf_howto_3: "农夫：从院子里拿一张你还缺的卡。没有适合你的卡：把院子里的一张卡送回去。",
    wf_howto_4: "目标：你的牧场上集齐五种动物。最先集齐的人获胜。",
