    game_zoowurf: "动物园掷骰",
    home_zoowurf_desc: "儿童骰子游戏：掷动物骰子，把卡片上画的动物（狮子、大象、长颈鹿、猴子和企鹅）凑齐。只有图画，不用识字，没有时间限制。可以对战电脑，也可以最多四人共用一台设备。",
    zoowurf_history_intro: "掷骰子和配对图画，是幼儿最早玩的游戏之一；这款游戏用动物园里的动物把两者结合在一起。",
    quickrules_zoowurf_1: "点一下两张明牌中的一张，卡上画着你要掷出的动物。",
    quickrules_zoowurf_2: "最多掷三次。掷出卡上动物或爪印的骰子留在卡上，其余的重新掷。",
    quickrules_zoowurf_3: "卡片凑满就归你，然后开始新的一轮；没凑满，由下一位玩家接着掷。先拿到四张卡的人获胜。",
