    game_klappenkasten: "Klappenkasten",
    home_klappenkasten_desc: "传统的骰子游戏：掷两个骰子，把加起来等于点数的编号翻板盖上。无法再盖时，还开着的翻板数字就是你的失分——总分最少者获胜，盖上全部翻板则立即获胜。可与电脑对战，或最多四人共用一台设备。",
    kk_history_intro: "一种带有一排编号翻板的传统骰子游戏，在酒馆和船上流行——它具体起源于何时何地并不确定。",
    quickrules_klappenkasten_1: "掷两个骰子，把编号加起来等于点数的翻板盖上——一块或几块都可以。",
    quickrules_klappenkasten_2: "继续掷骰和盖板。无法再盖时，还开着的翻板编号之和就是你的分数。",
    quickrules_klappenkasten_3: "分数最少者获胜；盖上全部翻板则立即获胜。“撤销”可以收回一次盖板。",
    kk_size_label: "翻板：",
