    sw_again_hint: "双六！再掷一次。",
    game_steckwuerfeln: "Steckwürfeln",
    home_steckwuerfeln_desc: "一种传统的插销骰子游戏，有编号 2 到 12 的十一个孔：掷两个骰子，把销插进点数之和的孔，或插进两个单独点数的孔。一直掷到没有孔可插为止——空着的孔就是你的失分，总分最少者获胜。变体：双六当作百搭，或共用一块板，插不下的人出局。",
    sw_history_intro: "一种在带编号孔的板上用销钉玩的小型传统骰子游戏——规则简单、历史悠久，至今仍作为木制袖珍游戏出售。",
    quickrules_steckwuerfeln_1: "掷两个骰子。把销插进点数之和的孔，或插进两个单独点数的孔（2 和 4：6 号孔，或 2 号和 4 号孔）。",
    quickrules_steckwuerfeln_2: "继续掷骰和插销。没有孔可插时，空着的孔的编号之和就是你的分数。",
    quickrules_steckwuerfeln_3: "分数最少者获胜。双六是百搭（再掷一次）。“撤销”可以收回一枚销。",
