    game_sternjagd: "Sternjagd",
    home_sternjagd_desc: "适合2至4人的单骰追逐游戏：掷出的点数就是沿着星形棋盘箭头必须走的步数。停在对手所在的格子上，就能拿走他三颗星中的一颗；只是经过则没有影响。最后还剩有星星的玩家获胜。",
    sj_history_intro: "使用骰子的追逐游戏在许多文化中都有传统；这个版本使用自己设计的带箭头棋盘。",
    quickrules_sternjagd_1: "掷骰子，沿箭头正好走那么多步。点按带圈的格子之一。",
    quickrules_sternjagd_2: "把走法停在对手身上就能抓住他：他失去一颗星，回到角上。只是经过则没有影响。",
    quickrules_sternjagd_3: "每人有三颗星。最后还剩有星星的玩家获胜。“撤销”可收回一步。",
    sj_roll: "掷骰子",
    sj_roll_hint: "请掷骰子。",
