    game_kleeberg: "Kleeberg",
    home_kleeberg_desc: "两人在圆形格子组成的金字塔上玩的搭建游戏：轮流把红心或四叶草放在空格上，但只能放在两个已填满的格子上方。自己的三个符号连成一条直线就获胜。",
    kb_history_intro: "Kleeberg 是一款规则独特的新游戏，源于“三子连线”这个古老的想法。",
    quickrules_kleeberg_1: "轮流下子：把红心或四叶草放在带圆圈的格子上。",
    quickrules_kleeberg_2: "向上搭建：只有下方两个格子都已填满，这个格子才开放。",
    quickrules_kleeberg_3: "自己的三个符号连成直线就获胜。金字塔填满而无人连成线则为平局。",
    kb_move_hint: "点按带圆圈的格子。虚线边框的格子还没有开放。",
    kb_hearts: "红心",
