    kq_cards_label: "卡片",
    game_oddone: "哪个不一样？",
    home_oddone_desc: "几张卡片在某一方面都相同，只有一张例外：点出不属于这一组的那张。有同一类的图画，也有某个特征一致的图形。每局六轮，三个难度，大号按钮，没有时间限制，卡住时可以看提示。",
    oddone_history_intro: "找出不属于同类的那一个，是课本和思维测验里的经典练习，能锻炼按特征给事物分类的能力。",
    quickrules_oddone_1: "几张卡片在某一方面相同，只有一张例外。",
