    game_shadowmatch: "这是谁的影子？",
    home_shadowmatch_desc: "一幅图画和几个黑色影子：哪个影子是它的？每局六幅图，三个难度——困难模式里，同一幅图还会以旋转或镜像的形式出现。大号按钮，没有时间限制，卡住时可以看提示。",
    shadowmatch_history_intro: "几百年来，人们描摹影子、剪下影子，还用影子来玩耍；把影子和物体配对，是一项小小的观察练习。",
    quickrules_shadowmatch_1: "上面是一幅图画，下面是几个黑色影子。",
