    game_catplaces: "猫咪的位置",
    home_catplaces_desc: "每一行、每一列和每个房间都恰好放一只猫，而且两只猫不能相邻，连角也不能碰。三种大小的逻辑谜题，每题只有一个解，无需猜测即可解开。",
    kz_history_intro: "规则来自2003年为在荷兰举行的世界谜题锦标赛设计的一种逻辑谜题；这里用睡觉的猫代替星星。",
