    game_rings: "转动圆环",
    home_rings_desc: "三到五个圆环一个套一个，上面画着图形。转动圆环，直到从中心向外的每条射线上都是同一种图形——困难模式下，一个圆环会带着相邻的圆环一起转。显示最少步数，还有提示按钮。",
    rg_history_intro: "带符号、可以相互转动的圆环由来已久：莱昂·巴蒂斯塔·阿尔伯蒂在1467年描述了由两个可转动圆环组成的密码盘。这里的谜题是为PaperGames制作的。",
    quickrules_rings_1: "用图下方的按钮把圆环向左 ↺ 或向右 ↻ 转动。",
    quickrules_rings_2: "目标：从中心向外的8条射线，每一条在所有圆环上都是同一种图形。",
    quickrules_rings_3: "困难模式下，转动一个圆环时，外侧的下一个圆环也会一起转。“提示”会给出一步好棋，并显示最少步数。",
