    game_matches: "火柴谜题",
    home_matches_desc: "移动一两根火柴，让错误的算式变对，或让图形出现指定数量的正方形。三个难度共90道题，每道都经电脑检验；先点一根火柴，再点一个空位——不用拖动。",
    mt_history_intro: "火柴在19世纪成了日常用品，很快也成了谜题材料：霍夫曼教授（Professor Hoffmann）1893年的书《Puzzles Old and New》里就已经有一章火柴谜题。",
    quickrules_matches_1: "点一根火柴把它拿起来，再点一个空位把它放下。",
