    game_tangram: "七巧板",
    home_tangram_desc: "用七块经典拼板——三角形、正方形和平行四边形——填满一个轮廓。四个难度共90个轮廓，每个都由电脑验证过解法。在“只有轮廓”中只看得到外线，拼板会落在你点的地方——需要反复尝试。点一块拼板，旋转，再点要放的位置——无需拖动。",
    tg_history_intro: "从一个正方形切出的七块拼板：这个谜题源自中国，现存最早的七巧板书籍印于1813年；从1817年起，它在欧洲风靡一时。",
    quickrules_tangram_1: "在轮廓下方选一块拼板，用“转45°”或“翻转”调整方向，然后点它该去的位置。",
